package com.rappistream.orderapi.domain;  import com.fasterxml.jackson.annotation.JsonProperty;  public record ErrorDetail(         @JsonProperty("field") String field,         @JsonProperty("reason") String reason) {      public ErrorDetail {         if (field == null || field.isBlank()) {             throw new IllegalArgumentException("field must not be blank");         }         if (reason == null || reason.isBlank()) {             throw new IllegalArgumentException("reason must not be blank");         }     } }
